element.style.setProperty('grid-template-columns', 'minmax(0,1fr) minmax(0,520px)', 'important');
element.style.setProperty('grid-template-areas', '"contentTop contentTop" "main sidebar" "contentBottom contentBottom"', 'important');
element.style.setProperty('max-width', '100%', 'important');
element.style.setProperty('gap', '24px', 'important');

// Move the sponsored content block into the sidebar region
const sidebar = document.querySelector('[data-region="sidebar"] .flex.flex-col');
if (!sidebar) return;
if (element.dataset.movedToSidebar === 'true') return;
sidebar.insertBefore(element, sidebar.firstChild);
element.dataset.movedToSidebar = 'true';

element.style.setProperty('background', '#ffffff', 'important');
element.style.setProperty('border-radius', '14px', 'important');
element.style.setProperty('overflow', 'hidden', 'important');
element.style.setProperty('box-shadow', '0 2px 8px rgba(0,0,0,0.07)', 'important');
element.style.setProperty('padding', '0', 'important');
element.style.setProperty('margin', '0', 'important');
element.style.setProperty('width', '100%', 'important');

element.style.setProperty('background', '#1a2744', 'important');
element.style.setProperty('border-radius', '16px 16px 0 0', 'important');
element.style.setProperty('padding', '14px 20px', 'important');
element.style.setProperty('margin', '0', 'important');

const h2 = element.querySelector('h2');
if (h2) {
  h2.style.setProperty('color', '#ffffff', 'important');
  h2.style.setProperty('font-size', '15px', 'important');
  h2.style.setProperty('letter-spacing', '0.08em', 'important');
  h2.style.setProperty('text-transform', 'uppercase', 'important');
  h2.style.setProperty('font-weight', '700', 'important');
}

element.style.setProperty('position', 'sticky', 'important');
element.style.setProperty('top', '80px', 'important');
element.style.setProperty('max-height', 'calc(100vh - 100px)', 'important');
element.style.setProperty('overflow-y', 'auto', 'important');
element.style.setProperty('padding', '0 4px 16px 4px', 'important');
element.style.setProperty('gap', '16px', 'important');
element.style.setProperty('scroll-behavior', 'smooth', 'important');

// Subtle scrollbar
element.style.setProperty('scrollbar-width', 'thin', 'important');
element.style.setProperty('scrollbar-color', '#c5cde8 transparent', 'important');
